-- Gujarat location master data (districts → talukas → places → SRO)
create extension if not exists pgcrypto with schema extensions;


create table if not exists public.gu_districts (
  id uuid primary key,
  name_en text not null unique,
  name_gu text,
  sort_order integer not null default 0,
  is_active boolean not null default true
);

create table if not exists public.gu_talukas (
  id uuid primary key,
  district_id uuid not null references public.gu_districts(id) on delete cascade,
  name_en text not null,
  name_gu text,
  sort_order integer not null default 0,
  is_active boolean not null default true,
  unique (district_id, name_en)
);

create table if not exists public.gu_places (
  id uuid primary key,
  district_id uuid not null references public.gu_districts(id) on delete cascade,
  taluka_id uuid not null references public.gu_talukas(id) on delete cascade,
  name_en text not null,
  name_gu text,
  place_type text not null default 'village' check (place_type in ('village', 'city', 'town')),
  sort_order integer not null default 0,
  is_active boolean not null default true,
  unique (taluka_id, name_en)
);

create table if not exists public.gu_sro_offices (
  id uuid primary key,
  district_id uuid not null references public.gu_districts(id) on delete cascade,
  name_en text not null,
  name_gu text,
  code text,
  sort_order integer not null default 0,
  is_active boolean not null default true,
  unique (district_id, name_en)
);

create table if not exists public.gu_sro_coverage (
  id uuid primary key default gen_random_uuid(),
  sro_id uuid not null references public.gu_sro_offices(id) on delete cascade,
  district_id uuid references public.gu_districts(id) on delete cascade,
  taluka_id uuid references public.gu_talukas(id) on delete cascade,
  place_id uuid references public.gu_places(id) on delete cascade,
  constraint gu_sro_coverage_scope check (taluka_id is not null or place_id is not null)
);

create index if not exists gu_talukas_district_id_idx on public.gu_talukas(district_id);
create index if not exists gu_places_taluka_id_idx on public.gu_places(taluka_id);
create index if not exists gu_sro_offices_district_id_idx on public.gu_sro_offices(district_id);
create index if not exists gu_sro_coverage_sro_id_idx on public.gu_sro_coverage(sro_id);
create index if not exists gu_sro_coverage_taluka_id_idx on public.gu_sro_coverage(taluka_id);
create index if not exists gu_sro_coverage_place_id_idx on public.gu_sro_coverage(place_id);

alter table public.gu_districts enable row level security;
alter table public.gu_talukas enable row level security;
alter table public.gu_places enable row level security;
alter table public.gu_sro_offices enable row level security;
alter table public.gu_sro_coverage enable row level security;

-- Public read for cascading dropdowns
drop policy if exists gu_districts_read on public.gu_districts;
drop policy if exists gu_talukas_read on public.gu_talukas;
drop policy if exists gu_places_read on public.gu_places;
drop policy if exists gu_sro_offices_read on public.gu_sro_offices;
drop policy if exists gu_sro_coverage_read on public.gu_sro_coverage;

create policy gu_districts_read on public.gu_districts for select to anon, authenticated using (is_active);
create policy gu_talukas_read on public.gu_talukas for select to anon, authenticated using (is_active);
create policy gu_places_read on public.gu_places for select to anon, authenticated using (is_active);
create policy gu_sro_offices_read on public.gu_sro_offices for select to anon, authenticated using (is_active);
create policy gu_sro_coverage_read on public.gu_sro_coverage for select to anon, authenticated using (true);

grant select on public.gu_districts to anon, authenticated;
grant select on public.gu_talukas to anon, authenticated;
grant select on public.gu_places to anon, authenticated;
grant select on public.gu_sro_offices to anon, authenticated;
grant select on public.gu_sro_coverage to anon, authenticated;

truncate table public.gu_sro_coverage, public.gu_sro_offices, public.gu_places, public.gu_talukas, public.gu_districts cascade;

create or replace function public.list_gu_districts()
returns json language sql stable security definer set search_path=public as $$
  select coalesce(json_agg(json_build_object(
    'id', id, 'nameEn', name_en, 'nameGu', name_gu
  ) order by sort_order, name_en), '[]'::json)
  from public.gu_districts where is_active;
$$;

create or replace function public.list_gu_talukas(p_district_id uuid)
returns json language sql stable security definer set search_path=public as $$
  select coalesce(json_agg(json_build_object(
    'id', id, 'districtId', district_id, 'nameEn', name_en, 'nameGu', name_gu
  ) order by sort_order, name_en), '[]'::json)
  from public.gu_talukas
  where is_active and district_id = p_district_id;
$$;

create or replace function public.list_gu_places(p_taluka_id uuid)
returns json language sql stable security definer set search_path=public as $$
  select coalesce(json_agg(json_build_object(
    'id', id, 'talukaId', taluka_id, 'districtId', district_id,
    'nameEn', name_en, 'nameGu', name_gu, 'placeType', place_type
  ) order by sort_order, name_en), '[]'::json)
  from public.gu_places
  where is_active and taluka_id = p_taluka_id;
$$;

create or replace function public.list_gu_sro_offices(
  p_district_id uuid,
  p_taluka_id uuid default null,
  p_place_id uuid default null
)
returns json
language plpgsql
stable
security definer
set search_path=public
as $$
declare
  v_result json;
begin
  -- Prefer place-specific coverage when place is selected
  if p_place_id is not null then
    select coalesce(json_agg(x order by x."sortOrder", x."nameEn"), '[]'::json)
      into v_result
    from (
      select distinct s.id, s.name_en as "nameEn", s.name_gu as "nameGu", s.code, s.sort_order as "sortOrder"
      from public.gu_sro_offices s
      join public.gu_sro_coverage c on c.sro_id = s.id
      where s.is_active and c.place_id = p_place_id
    ) x;
    if v_result is not null and json_array_length(v_result) > 0 then
      return v_result;
    end if;
  end if;

  if p_taluka_id is not null then
    select coalesce(json_agg(x order by x."sortOrder", x."nameEn"), '[]'::json)
      into v_result
    from (
      select distinct s.id, s.name_en as "nameEn", s.name_gu as "nameGu", s.code, s.sort_order as "sortOrder"
      from public.gu_sro_offices s
      join public.gu_sro_coverage c on c.sro_id = s.id
      where s.is_active and c.taluka_id = p_taluka_id
        and (c.place_id is null or p_place_id is null)
    ) x;
    if v_result is not null and json_array_length(v_result) > 0 then
      return v_result;
    end if;
  end if;

  select coalesce(json_agg(x order by x."sortOrder", x."nameEn"), '[]'::json)
    into v_result
  from (
    select s.id, s.name_en as "nameEn", s.name_gu as "nameGu", s.code, s.sort_order as "sortOrder"
    from public.gu_sro_offices s
    where s.is_active and s.district_id = p_district_id
  ) x;

  return coalesce(v_result, '[]'::json);
end;
$$;

revoke all on function public.list_gu_districts() from public;
revoke all on function public.list_gu_talukas(uuid) from public;
revoke all on function public.list_gu_places(uuid) from public;
revoke all on function public.list_gu_sro_offices(uuid, uuid, uuid) from public;
grant execute on function public.list_gu_districts() to anon, authenticated;
grant execute on function public.list_gu_talukas(uuid) to anon, authenticated;
grant execute on function public.list_gu_places(uuid) to anon, authenticated;
grant execute on function public.list_gu_sro_offices(uuid, uuid, uuid) to anon, authenticated;
